// Scheduler, threshold progress, and spoiler-safe projections. No game rules.
const invalid=()=>{throw Error('Invalid schedule or progress data. Nothing was applied.');};
const int=(n,min=0)=>{if(!Number.isSafeInteger(n)||n<min)invalid();};
const text=v=>{if(typeof v!=='string'||!v.trim()||v.length>5000)invalid();};
const exact=(o,ks)=>{if(!o||typeof o!=='object'||Array.isArray(o)||Object.keys(o).some(k=>!ks.includes(k)))invalid();};
const id=()=>crypto.randomUUID();
export const DAY_COUNT=100000;
export function createScheduler(){let stream='',cover='';for(let i=0;i<DAY_COUNT;i+=4096){const values=new Uint32Array(Math.min(4096,DAY_COUNT-i)*2);crypto.getRandomValues(values);for(let j=0;j<values.length;j+=2){stream+=values[j].toString(16).padStart(8,'0');cover+=values[j+1]<1431655765?'1':'0';}}return {version:1,stream,cover,events:[],remainder:null};}
function checksum(s){let crc=65535;for(const c of s){crc^=c.charCodeAt(0)<<8;for(let i=0;i<8;i++)crc=(crc&32768)?((crc<<1)^4129)&65535:(crc<<1)&65535;}return crc.toString(16).toUpperCase().padStart(4,'0');}
export function dayToken(s,day=s.current_day){if(!s.scheduler)return null;int(day);if(day>=DAY_COUNT)throw Error('Day is outside the pre-generated calendar (0–99,999).');const raw=`D${String(day).padStart(3,'0')}-${s.scheduler.stream.slice(day*8,day*8+8).toUpperCase()}`;return raw+'-'+checksum(raw);}
export function verifyToken(s,token){const m=/^D(\d{3,5})-[0-9A-F]{8}-[0-9A-F]{4}$/.exec(token);return !!m&&Number(m[1])<DAY_COUNT&&dayToken(s,Number(m[1]))===token;}
export function visibleEvents(s){return (s.scheduler?.events||[]).filter(e=>e.state==='triggered').map(e=>({id:e.id,state:e.state}));}
export function safeDisplay(value){if(Array.isArray(value))return value.map(safeDisplay);if(value&&typeof value==='object'){if(value.visibility==='dm_only')return {id:value.id,state:value.state||'sealed'};const out={};for(const [k,v]of Object.entries(value)){if(['stream','cover','operations_key','eligible_from_day','must_fire_by_day','fires_on_day','triggered_on_day','processed_on_day','depends_on_id','revisions'].includes(k))continue;if(k==='packet'){out.packet='Stored privately';}else if(k==='events'){out.events=Array.isArray(v)?v.filter(e=>e.state==='triggered'||e.state==='resolved').map(e=>({id:e.id,state:e.state})):[];}else if(k==='scheduler')out.scheduler={active:true};else out[k]=safeDisplay(v);}return out;}return value;}
export function schedulerProjection(s){return {active:!!s.scheduler,unresolved:visibleEvents(s)};}
export function validateScheduler(s){if(s.scheduler!==undefined){exact(s.scheduler,['version','stream','cover','events','remainder']);if(typeof s.scheduler.cover!=='string'||s.scheduler.cover.length!==DAY_COUNT||!/^[01]+$/.test(s.scheduler.cover))invalid();if(s.scheduler.remainder!==null){exact(s.scheduler.remainder,['target_day']);int(s.scheduler.remainder.target_day);if(s.scheduler.remainder.target_day>=DAY_COUNT)invalid();}if(s.scheduler.version!==1||typeof s.scheduler.stream!=='string'||s.scheduler.stream.length!==DAY_COUNT*8||!/^[0-9a-f]+$/.test(s.scheduler.stream))invalid();if(!Array.isArray(s.scheduler.events)||s.scheduler.events.length>10000)invalid();const ids=new Set();for(const e of s.scheduler.events){exact(e,['id','visibility','label','eligible_from_day','must_fire_by_day','selection_rule','fires_on_day','state','triggered_on_day','processed_on_day','deliveries','resolved_at','revisions','alias','depends_on_id']);text(e.id);if(ids.has(e.id))invalid();ids.add(e.id);if(!['dm_only','player'].includes(e.visibility)||e.visibility==='dm_only'&&e.label!==null)invalid();for(const k of ['eligible_from_day','must_fire_by_day','fires_on_day']){if(e.selection_rule!=='trigger_chain'){int(e[k]);if(e[k]>=DAY_COUNT)invalid();}}if(e.selection_rule==='trigger_chain'){if(e.fires_on_day!==null||!e.depends_on_id)invalid();continue;}if(e.eligible_from_day>e.fires_on_day||e.fires_on_day>e.must_fire_by_day||!['first_day','last_day','random'].includes(e.selection_rule)||!['scheduled','triggered','resolved'].includes(e.state))invalid();if(!Array.isArray(e.deliveries)||!Array.isArray(e.revisions))invalid();if(e.state!=='scheduled'){int(e.triggered_on_day);int(e.processed_on_day);}else if(e.triggered_on_day!==null||e.processed_on_day!==null)invalid();}}
 if(s.thresholds!==undefined){if(!Array.isArray(s.thresholds))invalid();for(const t of s.thresholds){text(t.id);text(t.label);if(!s.characters.some(c=>c.character_id===t.character_id)||!Array.isArray(t.stages)||!t.stages.length)invalid();for(const [i,g]of t.stages.entries()){if(g.stage_index!==i)invalid();int(g.required,1);if(typeof g.consecutive_required!=='boolean')invalid();for(const k of ['successes','streak'])if(g.baseline[k]!=='unknown')int(g.baseline[k]);if(!Array.isArray(g.dc_revisions)||!Array.isArray(g.attempts))invalid();for(const d of g.dc_revisions){text(d.revision_id);int(d.dc,-Number.MAX_SAFE_INTEGER);}for(const a of g.attempts){if(!['success','failure'].includes(a.result)||!g.dc_revisions.some(d=>d.revision_id===a.dc_revision_id))invalid();}}}}
}
export function stageProgress(g){let successes=g.baseline.successes,streak=g.baseline.streak;for(const a of g.attempts){if(a.superseded)continue;if(a.result==='success'){if(successes!=='unknown')successes++;if(streak!=='unknown')streak++;}else streak=0;}return {successes,streak,complete:(g.consecutive_required?streak:successes)!=='unknown'&&(g.consecutive_required?streak:successes)>=g.required};}
export function thresholdProgress(t){const stages=t.stages.map(stageProgress);return {stages,current_stage_index:stages.findIndex(g=>!g.complete),complete:stages.every(g=>g.complete)};}
export function activate(s){if(s.scheduler)throw Error('Scheduler is already active.');s.scheduler=createScheduler();s.thresholds=structuredClone(s.pending_migration?.thresholds||[]);}
function selected(s,o){text(o.character_id);text(o.reason);const c=s.characters.find(c=>c.character_id===o.character_id);if(!c)invalid();return c;}
export function applyExtended(s,o){
 if(o.op==='activate_scheduler'){exact(o,['op','character_id','reason']);activate(s);return true;}
 if(['set_xp','set_currency','set_level_threshold'].includes(o.op)){const c=selected(s,o);exact(o,['op','character_id','reason',...(o.op==='set_level_threshold'?['level','cumulative_xp']:['value'])]);if(o.op==='set_level_threshold'){int(o.level,1);if(o.cumulative_xp!=='unknown')int(o.cumulative_xp);s.level_thresholds[String(o.level)]=o.cumulative_xp;}else{int(o.value,o.op==='set_xp'?0:-Number.MAX_SAFE_INTEGER);c[o.op==='set_xp'?'xp_total':'currency_amount']=o.value;}return true;}
 if(o.op==='log_threshold_attempt'){selected(s,o);exact(o,['op','character_id','threshold_id','stage_index','result','dc_revision_id','reason']);const t=s.thresholds?.find(t=>t.id===o.threshold_id&&t.character_id===o.character_id);if(!t)throw Error('Unknown active threshold.');const p=thresholdProgress(t);if(p.complete||t.completed_on_day!==null||o.stage_index!==p.current_stage_index)throw Error('Attempt must target the current unfinished stage.');const g=t.stages[o.stage_index];if(!['success','failure'].includes(o.result)||!g.dc_revisions.some(d=>d.revision_id===o.dc_revision_id))throw Error('Use a recorded DC revision and success or failure.');g.attempts.push({attempt_seq:g.attempts.length+1,result:o.result,dc_revision_id:o.dc_revision_id,superseded:false});if(thresholdProgress(t).complete)t.completed_on_day=s.current_day;return true;}
 if(o.op==='set_threshold_dc'){selected(s,o);exact(o,['op','character_id','threshold_id','stage_index','dc','reason']);const t=s.thresholds?.find(t=>t.id===o.threshold_id&&t.character_id===o.character_id);const g=t?.stages[o.stage_index];if(!g)invalid();int(o.dc,-Number.MAX_SAFE_INTEGER);g.dc_revisions.push({revision_id:id(),dc:o.dc,set_on_day:s.current_day});return true;}
 if(o.op==='set_session_notes'){exact(o,['op','session_id','notes']);const session=s.sessions.find(x=>x.session_id===o.session_id);if(!session||typeof o.notes!=='string'||o.notes.length>100000)invalid();session.notes=o.notes;return true;}
 if(o.op==='resolve_event'){exact(o,['op','character_id','event_id','reason']);if(o.reason!=='resolved')invalid();const e=s.scheduler?.events.find(e=>e.id===o.event_id);if(!e||e.state!=='triggered')throw Error('Only an unresolved triggered event can be resolved.');e.state='resolved';e.resolved_at=new Date().toISOString();return true;}
 if(o.op==='record_delivery'){exact(o,['op','reason']);if(o.reason!=='delivered')invalid();for(const e of s.scheduler?.events||[])if(e.state==='triggered')e.deliveries.push({handoff_id:id(),generated_at:new Date().toISOString()});return true;}
 if(['schedule_event','amend_event_date'].includes(o.op)){if(!s.scheduler)invalid();exact(o,['op','character_id','reason','event_id','visibility','label','eligible_from_day','must_fire_by_day','selection_rule','import_historical']);selected(s,o);if(!['created','date_amended','imported'].includes(o.reason))invalid();scheduleEvent(s,o);return true;}
 if(o.op==='configure_migrated_events'){selected(s,o);exact(o,['op','character_id','reason','rules']);if(o.reason!=='imported'||!s.scheduler||s.scheduler.events.length||!s.pending_migration)invalid();if(!Array.isArray(o.rules))invalid();const mapping={};for(const e of s.pending_migration.events)mapping[e.id]=id();for(const raw of s.pending_migration.events){const rule=o.rules.find(r=>r.id===raw.id);if(rule)exact(rule,['id','selection_rule']);if(raw.depends_on_id){s.scheduler.events.push({id:mapping[raw.id],alias:raw.id,visibility:'dm_only',label:null,selection_rule:'trigger_chain',eligible_from_day:null,must_fire_by_day:null,fires_on_day:null,depends_on_id:mapping[raw.depends_on_id]||raw.depends_on_id,state:'scheduled',triggered_on_day:null,processed_on_day:null,deliveries:[],resolved_at:null,revisions:[]});continue;}const fixed=Number.isSafeInteger(raw.fires_on_day);scheduleEvent(s,{visibility:'dm_only',eligible_from_day:fixed?raw.fires_on_day:raw.eligible_from_day,must_fire_by_day:fixed?raw.fires_on_day:raw.must_fire_by_day,selection_rule:fixed?'first_day':rule?.selection_rule,import_historical:true},mapping[raw.id],raw.id);}s.pending_migration=null;return true;}
 if(o.op==='set_ability_detail'){const c=selected(s,o);exact(o,['op','character_id','reason','slot_index','slot_name','application_name','status','threshold_id','cost','range','effect','notes']);int(o.slot_index,1);text(o.application_name);if(!['locked','trained_unquantified','in_development'].includes(o.status))invalid();if(!s.ability_slots_enabled)throw Error('Ability slots are disabled in this campaign.');const slot=c.ability_slots?.find(x=>x.index===o.slot_index);if(!slot)throw Error('Unknown ability slot.');if(o.status==='in_development'&&!s.thresholds?.some(t=>t.id===o.threshold_id&&t.character_id===o.character_id))throw Error('In-development abilities require a linked character threshold.');slot.applications ||= [];const i=slot.applications.findIndex(a=>(typeof a==='string'?a:a.name)===o.application_name);const old=i<0?{}:typeof slot.applications[i]==='string'?{}:slot.applications[i];const a={...old,name:o.application_name,status:o.status};for(const k of ['cost','range','effect','notes']){if(o[k]!==undefined){if(typeof o[k]!=='string'||o[k].length>5000)invalid();a[k]=o[k].trim()||'not yet quantified';}else a[k] ||= 'not yet quantified';}if(o.threshold_id!==undefined)a.threshold_id=o.threshold_id;if(o.status!=='in_development')delete a.threshold_id;if(i<0)slot.applications.push(a);else slot.applications[i]=a;if(o.slot_name!==undefined){text(o.slot_name);slot.name=o.slot_name;}else if(!slot.name)slot.name=o.application_name;c.reference_revision++;return true;}

 return false;
}
function randomBelow(n){const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a);}while(a[0]>=limit);return a[0]%n;}
// This plan is internal only. Never render a reached day until the transaction commits.
export function planAdvance(s,o){if(!s.scheduler)throw Error('Activate the calendar before advancing.');int(o.to_day);if(o.to_day<=s.current_day)throw Error('Choose a later day.');if(o.to_day>=DAY_COUNT)throw Error('Day is outside the pre-generated calendar (0–99,999).');if(o.skip_through)return o.to_day;const due=s.scheduler.events.filter(e=>e.state==='scheduled'&&e.selection_rule!=='trigger_chain'&&e.fires_on_day<=o.to_day).reduce((n,e)=>Math.min(n,Math.max(s.current_day+1,e.fires_on_day)),o.to_day);for(let d=s.current_day+1;d<=due;d++)if(s.scheduler.cover[d]==='1')return d;return due;}
export function advance(s,o){const reached=planAdvance(s,o);for(const e of s.scheduler.events){if(e.state==='scheduled'&&e.selection_rule!=='trigger_chain'&&e.fires_on_day<=reached){e.state='triggered';e.triggered_on_day=e.fires_on_day;e.processed_on_day=reached;}}s.scheduler.remainder=reached<o.to_day?{target_day:o.to_day}:null;for(const session of s.sessions)if(session.state==='open')session.advance_submitted=true;s.current_day=reached;}

function scheduleEvent(s,raw,newID=id(),alias){if(!['dm_only','player'].includes(raw.visibility)||raw.visibility==='dm_only'&&raw.label!==undefined&&raw.label!==null)invalid();for(const k of ['eligible_from_day','must_fire_by_day']){int(raw[k]);if(raw[k]>=DAY_COUNT)invalid();}if(raw.eligible_from_day>raw.must_fire_by_day||!['first_day','last_day','random'].includes(raw.selection_rule))invalid();const old=raw.event_id?s.scheduler.events.find(e=>e.id===raw.event_id):null;if(raw.op==='amend_event_date'&&!old)invalid();if(raw.op==='schedule_event'&&raw.event_id!==undefined)invalid();const chosen=raw.selection_rule==='first_day'?raw.eligible_from_day:raw.selection_rule==='last_day'?raw.must_fire_by_day:raw.eligible_from_day+randomBelow(raw.must_fire_by_day-raw.eligible_from_day+1);if(!old&&chosen<=s.current_day&&!raw.import_historical)throw Error('An elapsed event needs explicit historical-import approval.');const e=old||{id:newID,...(alias?{alias}:{}),state:'scheduled',triggered_on_day:null,processed_on_day:null,deliveries:[],resolved_at:null,revisions:[]};if(old)e.revisions.push({changed_on:new Date().toISOString(),field:'schedule',from:{eligible_from_day:e.eligible_from_day,must_fire_by_day:e.must_fire_by_day,fires_on_day:e.fires_on_day},to:{eligible_from_day:raw.eligible_from_day,must_fire_by_day:raw.must_fire_by_day,fires_on_day:chosen},reason:'date_amended'});Object.assign(e,{visibility:raw.visibility,label:raw.visibility==='dm_only'?null:raw.label||null,eligible_from_day:raw.eligible_from_day,must_fire_by_day:raw.must_fire_by_day,selection_rule:raw.selection_rule,fires_on_day:chosen});if(!old){if(chosen<=s.current_day){e.state='triggered';e.triggered_on_day=chosen;e.processed_on_day=s.current_day;}s.scheduler.events.push(e);}}

